function norm(v){ if(v===null||v===undefined||v==='')return '';
  if(typeof v==='number'){const ms=Math.round((v-25569)*86400000);
    return new Date(ms).toISOString().slice(0,19).replace('T',' ');}
  const s=String(v).trim().replace('T',' ');
  const m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ ]?(\d{1,2})?:?(\d{1,2})?:?(\d{1,2})?/);
  if(!m)return s; const p=(x,n)=>String(x||0).padStart(n,'0');
  return `${m[1]}-${p(m[2],2)}-${p(m[3],2)} ${p(m[4],2)}:${p(m[5],2)}:${p(m[6],2)}`; }
function objs(vals){ if(!vals||!vals.length)return [];
  const h=vals[0].map(x=>String(x).trim());
  return vals.slice(1).map(r=>{const o={};h.forEach((k,j)=>o[k]=r[j]);return o;}); }

const vr=$input.first().json.valueRanges||[];
const preds=objs((vr[0]||{}).values).filter(p=>p.dt_local&&p.decision);
const acts =objs((vr[1]||{}).values).filter(a=>a.dt_local);
const actMap=new Map(acts.map(a=>[norm(a.dt_local),a]));

// 최신 실적 시각 기준 7일 (실행 시각이 아니라 데이터 기준 — 결정적)
const times=acts.map(a=>norm(a.dt_local)).filter(Boolean).sort();
const last = times.length? new Date(times[times.length-1].replace(' ','T')) : null;
const wkAgo = last? new Date(last.getTime()-7*24*3600*1000) : null;

function metrics(rows){
  let n=0,hit=0,sHalf=0,sRT=0,sDA=0,worst=null;
  const byClass={};
  for(const p of rows){
    const a=actMap.get(norm(p.dt_local)); if(!a||a.dart===''||a.dart===undefined) continue;
    const dart=Number(a.dart), da=Number(a.da_spp), rt=Number(a.rt_spp);
    if(!isFinite(dart)||!isFinite(da)||!isFinite(rt)) continue;
    const half=(da+rt)/2; let cost,ok;
    if(p.decision==='BUY_DA'){cost=da;ok=dart<0;}
    else if(p.decision==='BUY_RT'){cost=rt;ok=dart>0;}
    else {cost=half;ok=Math.abs(dart)<=1;}
    n++; if(ok)hit++;
    sHalf+=half-cost; sRT+=rt-cost; sDA+=da-cost;
    const c=byClass[p.decision]||(byClass[p.decision]={n:0,hit:0}); c.n++; if(ok)c.hit++;
    const loss=cost-Math.min(da,rt);
    if(!worst||loss>worst.loss) worst={dt:p.dt_local,decision:p.decision,dart:+dart.toFixed(2),loss:+loss.toFixed(2)};
  }
  const r=x=>n?+(x/n).toFixed(3):null;
  return {n,hit_rate:r(hit),save_vs_half:r(sHalf),save_vs_rt:r(sRT),save_vs_da:r(sDA),
    by_class:Object.fromEntries(Object.entries(byClass).map(([k,v])=>[k,{n:v.n,hit:+(v.hit/v.n).toFixed(3)}])),
    worst_hour:worst};
}
const last7 = wkAgo? preds.filter(p=>{const t=new Date(norm(p.dt_local).replace(' ','T'));return t>wkAgo&&t<=last;}) : [];
return [{json:{ week_ending: last? norm(last.toISOString()).slice(0,10) : '',
  n_pred: preds.length, n_act: acts.length,
  last7: metrics(last7), cumulative: metrics(preds),
  analysis_header: (((vr[2]||{}).values)||[[]])[0]||[] }}];

const m=$('Compute metrics').first().json;
const resp=$input.first().json;
const text=(resp.content&&resp.content[0]&&resp.content[0].text)?resp.content[0].text:JSON.stringify(resp).slice(0,500);
const row={ week_ending:m.week_ending, n_hours_7d:m.last7.n, hit_7d:m.last7.hit_rate,
  save_vs_half_7d:m.last7.save_vs_half, save_vs_rt_7d:m.last7.save_vs_rt,
  hit_cum:m.cumulative.hit_rate, save_vs_rt_cum:m.cumulative.save_vs_rt,
  worst_hour_7d:m.last7.worst_hour?`${m.last7.worst_hour.dt} ${m.last7.worst_hour.decision} loss$${m.last7.worst_hour.loss}`:'',
  claude_analysis:text };
const hdr=m.analysis_header.length?m.analysis_header:Object.keys(row);
const values=[hdr.map(h=>{const v=row[String(h).trim()];return (v===undefined||v===null)?'':v;})];
return [{json:{tab:'analysis',values,n:1}}];
